CREATE TABLE IF NOT EXISTS menu_categories(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS menu_items(id BIGSERIAL PRIMARY KEY,category_id BIGINT REFERENCES menu_categories(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price_minor BIGINT NOT NULL CHECK(price_minor>=0),available BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders(id BIGSERIAL PRIMARY KEY,order_number TEXT UNIQUE NOT NULL,customer_name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',total_minor BIGINT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS order_lines(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),menu_item_id BIGINT REFERENCES menu_items(id),quantity INT NOT NULL,unit_price_minor BIGINT NOT NULL);